# Grammaire allemande, expliquée dans les autres langues d'interface.
T = {
'aussprache': {
 'es': ('Pronunciación', "ä, ö, ü: vocales con diéresis (Bär, schön, über; la ü como una «i» con los labios redondeados). ei suena «ai» (mein), ie es una «i» larga (Liebe), eu / äu suenan «oi» (heute, Häuser).\nch: suave tras e, i, ä, ö, ü y consonantes (ich, Milch); áspero tras a, o, u, como la «j» española (Bach, Buch). sch = «sh» (Schule). z = «ts» (Zeit). w = «v» labiodental (Wasser), v = «f» (Vater). s ante vocal = «z» sonora (Sonne); sp y st al inicio = «shp», «sht» (Sport, Straße). ß = «ss».\nLas consonantes finales se ensordecen: Tag suena «tak».\nh tras vocal es muda y la alarga (Kuh); en otros casos se aspira (Haus).\nEl acento cae en la primera sílaba de la raíz (Arbeit, verstehen).", ['Hablo un poco de alemán.', 'La calle es bonita.']),
 'it': ('Pronuncia', "ä, ö, ü: vocali con dieresi (Bär, schön, über; ü come una «i» con le labbra arrotondate). ei si legge «ai» (mein), ie è una «i» lunga (Liebe), eu / äu si leggono «oi» (heute, Häuser).\nch: dolce dopo e, i, ä, ö, ü e consonanti (ich, Milch); aspro dopo a, o, u (Bach, Buch). sch = «sc» di «scena» (Schule). z = «ts» (Zeit). w = «v» (Wasser), v = «f» (Vater). s davanti a vocale = «s» sonora (Sonne); sp e st a inizio parola = «scp», «sct» (Sport, Straße). ß = «ss».\nLe consonanti finali si assordiscono: Tag si legge «tak».\nh dopo vocale è muta e la allunga (Kuh); altrove è aspirata (Haus).\nL'accento cade sulla prima sillaba della radice (Arbeit, verstehen).", ['Parlo un po\' di tedesco.', 'La strada è bella.']),
 'pt': ('Pronúncia', "ä, ö, ü: vogais com trema (Bär, schön, über; ü como um «i» com os lábios arredondados). ei soa «ai» (mein), ie é um «i» longo (Liebe), eu / äu soam «ói» (heute, Häuser).\nch: suave depois de e, i, ä, ö, ü e consoantes (ich, Milch); áspero depois de a, o, u (Bach, Buch). sch = «ch» português (Schule). z = «ts» (Zeit). w = «v» (Wasser), v = «f» (Vater). s antes de vogal = «z» (Sonne); sp e st no início = «chp», «cht» (Sport, Straße). ß = «ss».\nConsoantes finais ficam surdas: Tag soa «tak».\nh depois de vogal é mudo e a alonga (Kuh); nos outros casos é aspirado (Haus).\nO acento cai na primeira sílaba do radical (Arbeit, verstehen).", ['Falo um pouco de alemão.', 'A rua é bonita.']),
 'ja': ('発音', "ä, ö, ü はウムラウト（Bär, schön, über。ü は「イ」の口を丸めた音）。ei は「アイ」（mein）、ie は長い「イー」（Liebe）、eu / äu は「オイ」（heute, Häuser）。\nch は e, i, ä, ö, ü や子音の後では「ヒ」（ich, Milch）、a, o, u の後では喉の奥の「ハ」（Bach, Buch）。sch は「シュ」（Schule）。z は「ツ」（Zeit）。w は「ヴ」（Wasser）、v は「フ」（Vater）。母音の前の s は「ズ」（Sonne）、語頭の sp, st は「シュプ」「シュト」（Sport, Straße）。ß は「ス」。\n語末の子音は無声になります：Tag は「ターク」。\n母音の後の h は発音せず母音を長くします（Kuh）。それ以外は息の音です（Haus）。\nアクセントは語幹の最初の音節（Arbeit, verstehen）。", ['ドイツ語を少し話します。', '通りがきれいです。']),
 'zh': ('发音', "ä, ö, ü 为变元音（Bär, schön, über；ü 类似汉语的「ü」）。ei 读「ai」（mein），ie 读长「i」（Liebe），eu / äu 读「oi」（heute, Häuser）。\nch 在 e, i, ä, ö, ü 和辅音后读轻的「x」（ich, Milch），在 a, o, u 后读喉音「h」（Bach, Buch）。sch 读「sh」（Schule）。z 读「ts」（Zeit）。w 读「v」（Wasser），v 读「f」（Vater）。元音前的 s 读浊音「z」（Sonne）；词首 sp、st 读「shp」「sht」（Sport, Straße）。ß 读「ss」。\n词尾辅音清化：Tag 读「tak」。\n元音后的 h 不发音并使元音变长（Kuh），其他位置送气（Haus）。\n重音在词根第一个音节（Arbeit, verstehen）。", ['我会说一点德语。', '这条街很漂亮。']),
 'ko': ('발음', "ä, ö, ü는 움라우트 모음입니다(Bär, schön, über, ü는 「위」를 입술을 둥글게 한 채 내는 소리). ei는 「아이」(mein), ie는 긴 「이」(Liebe), eu / äu는 「오이」(heute, Häuser).\nch는 e, i, ä, ö, ü와 자음 뒤에서 「히」(ich, Milch), a, o, u 뒤에서 목 깊은 「흐」(Bach, Buch). sch는 「슈」(Schule). z는 「츠」(Zeit). w는 「v」(Wasser), v는 「f」(Vater). 모음 앞의 s는 「z」(Sonne), 단어 처음의 sp, st는 「슈프」, 「슈트」(Sport, Straße). ß는 「ss」.\n단어 끝 자음은 무성음이 됩니다: Tag는 「탁」.\n모음 뒤의 h는 소리 나지 않고 모음을 길게 합니다(Kuh). 그 밖에는 숨소리입니다(Haus).\n강세는 어간의 첫 음절에 옵니다(Arbeit, verstehen).", ['독일어를 조금 해요.', '거리가 예뻐요.']),
 'lt': ('Tarimas', "ä, ö, ü – balsiai su umliautu (Bär, schön, über; ü kaip „i“ suapvalintomis lūpomis). ei tariamas „ai“ (mein), ie – ilgas „y“ (Liebe), eu / äu – „oi“ (heute, Häuser).\nch: minkštas po e, i, ä, ö, ü ir priebalsių (ich, Milch), gerklinis po a, o, u (Bach, Buch). sch = „š“ (Schule). z = „c“ (Zeit). w = „v“ (Wasser), v = „f“ (Vater). s prieš balsį = „z“ (Sonne); sp ir st žodžio pradžioje = „šp“, „št“ (Sport, Straße). ß = „s“.\nGaliniai priebalsiai suduslėja: Tag tariamas „tak“.\nh po balsio netariama ir pailgina balsį (Kuh); kitur tariama (Haus).\nKirtis krinta ant pirmojo šaknies skiemens (Arbeit, verstehen).", ['Kalbu truputį vokiškai.', 'Gatvė graži.']),
 'tl': ('Pagbigkas', "ä, ö, ü: patinig na may umlaut (Bär, schön, über; ang ü ay parang «i» na nakabilog ang labi). Ang ei ay «ay» (mein), ang ie ay mahabang «i» (Liebe), ang eu / äu ay «oy» (heute, Häuser).\nch: malambot pagkatapos ng e, i, ä, ö, ü at katinig (ich, Milch); magaspang pagkatapos ng a, o, u (Bach, Buch). sch = «sh» (Schule). z = «ts» (Zeit). w = «v» (Wasser), v = «f» (Vater). s bago patinig = «z» (Sonne); sp at st sa simula = «shp», «sht» (Sport, Straße). ß = «ss».\nNawawalan ng tinig ang huling katinig: Tag ay «tak».\nAng h pagkatapos ng patinig ay walang tunog at pinahahaba ito (Kuh); sa iba, may hininga (Haus).\nNasa unang pantig ng ugat ang diin (Arbeit, verstehen).", ['Nagsasalita ako ng kaunting Aleman.', 'Maganda ang kalye.']),
},
'genre': {
 'es': ('Los tres géneros y los artículos', "Tres géneros: masculino (der), femenino (die), neutro (das); el plural siempre es «die». El género se aprende con el sustantivo. Pistas: -ung, -heit, -keit, -schaft, -ion son femeninos; -chen, -lein, neutros; días, meses y estaciones, masculinos.\nIndefinido: ein (masculino, neutro), eine (femenino). Para negar un sustantivo: kein, keine.\nTodos los sustantivos se escriben con mayúscula.", ['El hombre, la mujer, el niño.', 'No tengo tiempo.']),
 'it': ('I tre generi e gli articoli', "Tre generi: maschile (der), femminile (die), neutro (das); il plurale è sempre «die». Il genere si impara con il nome. Indizi: -ung, -heit, -keit, -schaft, -ion sono femminili; -chen, -lein neutri; giorni, mesi e stagioni maschili.\nIndeterminativo: ein (maschile, neutro), eine (femminile). Per negare un nome: kein, keine.\nTutti i nomi hanno la maiuscola.", ["L'uomo, la donna, il bambino.", 'Non ho tempo.']),
 'pt': ('Os três gêneros e os artigos', "Três gêneros: masculino (der), feminino (die), neutro (das); o plural é sempre «die». O gênero aprende-se com o substantivo. Pistas: -ung, -heit, -keit, -schaft, -ion são femininos; -chen, -lein, neutros; dias, meses e estações, masculinos.\nIndefinido: ein (masculino, neutro), eine (feminino). Para negar um substantivo: kein, keine.\nTodos os substantivos levam maiúscula.", ['O homem, a mulher, a criança.', 'Não tenho tempo.']),
 'ja': ('三つの性と冠詞', "名詞には男性（der）、女性（die）、中性（das）があり、複数形はいつも「die」。性は名詞といっしょに覚えます。目安：-ung, -heit, -keit, -schaft, -ion は女性、-chen, -lein は中性、曜日・月・季節は男性。\n不定冠詞：ein（男性・中性）、eine（女性）。名詞の否定：kein, keine。\n名詞はすべて大文字で書き始めます。", ['男性、女性、子供。', '時間がありません。']),
 'zh': ('三种性与冠词', "名词有阳性（der）、阴性（die）、中性（das）三种性，复数一律用「die」。名词的性要和名词一起记。线索：-ung, -heit, -keit, -schaft, -ion 为阴性；-chen, -lein 为中性；星期、月份、季节为阳性。\n不定冠词：ein（阳性、中性），eine（阴性）。否定名词用：kein, keine。\n所有名词首字母大写。", ['男人、女人、孩子。', '我没有时间。']),
 'ko': ('세 가지 성과 관사', "명사에는 남성(der), 여성(die), 중성(das)이 있고 복수는 항상 「die」입니다. 성은 명사와 함께 외웁니다. 힌트: -ung, -heit, -keit, -schaft, -ion은 여성, -chen, -lein은 중성, 요일·달·계절은 남성.\n부정관사: ein(남성, 중성), eine(여성). 명사를 부정할 때: kein, keine.\n모든 명사는 대문자로 시작합니다.", ['남자, 여자, 아이.', '시간이 없어요.']),
 'lt': ('Trys giminės ir artikeliai', "Trys giminės: vyriškoji (der), moteriškoji (die), bevardė (das); daugiskaita visada „die“. Giminė mokomasi kartu su daiktavardžiu. Užuominos: -ung, -heit, -keit, -schaft, -ion – moteriškoji; -chen, -lein – bevardė; dienos, mėnesiai ir metų laikai – vyriškoji.\nNežymimasis: ein (vyr., bevardė), eine (mot.). Daiktavardžio neiginys: kein, keine.\nVisi daiktavardžiai rašomi didžiąja raide.", ['Vyras, moteris, vaikas.', 'Neturiu laiko.']),
 'tl': ('Tatlong kasarian at mga pantukoy', "Tatlong kasarian: panlalaki (der), pambabae (die), walang kasarian (das); laging «die» ang maramihan. Isinasaulo ang kasarian kasama ng pangngalan. Palatandaan: pambabae ang -ung, -heit, -keit, -schaft, -ion; walang kasarian ang -chen, -lein; panlalaki ang mga araw, buwan at panahon.\nDi-tiyak: ein (panlalaki, walang kasarian), eine (pambabae). Pang-negatibo sa pangngalan: kein, keine.\nMalaking titik ang simula ng lahat ng pangngalan.", ['Ang lalaki, ang babae, ang bata.', 'Wala akong oras.']),
},
'present': {
 'es': ('El presente', "Raíz + e, st, t, en, t, en: ich mache, du machst, er macht, wir machen, ihr macht, sie machen.\nsein: bin, bist, ist, sind, seid, sind. haben: habe, hast, hat, haben, habt, haben.\nVerbos fuertes: la vocal cambia con du y er (fahren → du fährst, sehen → er sieht, sprechen → er spricht).\nUsted: Sie + forma en -en.", ['Estoy cansado.', 'Él habla alemán.', '¿Tienes hambre?']),
 'it': ('Il presente', "Radice + e, st, t, en, t, en: ich mache, du machst, er macht, wir machen, ihr macht, sie machen.\nsein: bin, bist, ist, sind, seid, sind. haben: habe, hast, hat, haben, habt, haben.\nVerbi forti: la vocale cambia con du ed er (fahren → du fährst, sehen → er sieht, sprechen → er spricht).\nForma di cortesia: Sie + forma in -en.", ['Sono stanco.', 'Parla tedesco.', 'Hai fame?']),
 'pt': ('O presente', "Radical + e, st, t, en, t, en: ich mache, du machst, er macht, wir machen, ihr macht, sie machen.\nsein: bin, bist, ist, sind, seid, sind. haben: habe, hast, hat, haben, habt, haben.\nVerbos fortes: a vogal muda com du e er (fahren → du fährst, sehen → er sieht, sprechen → er spricht).\nTratamento formal: Sie + forma em -en.", ['Estou cansado.', 'Ele fala alemão.', 'Você está com fome?']),
 'ja': ('現在形', "語幹 + e, st, t, en, t, en：ich mache, du machst, er macht, wir machen, ihr macht, sie machen。\nsein：bin, bist, ist, sind, seid, sind。haben：habe, hast, hat, haben, habt, haben。\n強変化動詞は du と er で母音が変わります（fahren → du fährst, sehen → er sieht, sprechen → er spricht）。\n敬称：Sie + -en の形。", ['疲れています。', '彼はドイツ語を話します。', 'お腹すいた？']),
 'zh': ('现在时', "词干 + e, st, t, en, t, en：ich mache, du machst, er macht, wir machen, ihr macht, sie machen。\nsein：bin, bist, ist, sind, seid, sind。haben：habe, hast, hat, haben, habt, haben。\n强变化动词在 du 和 er 时元音改变（fahren → du fährst，sehen → er sieht，sprechen → er spricht）。\n尊称：Sie + -en 形式。", ['我累了。', '他说德语。', '你饿了吗？']),
 'ko': ('현재형', "어간 + e, st, t, en, t, en: ich mache, du machst, er macht, wir machen, ihr macht, sie machen.\nsein: bin, bist, ist, sind, seid, sind. haben: habe, hast, hat, haben, habt, haben.\n강변화 동사는 du와 er에서 모음이 바뀝니다(fahren → du fährst, sehen → er sieht, sprechen → er spricht).\n존칭: Sie + -en 형태.", ['피곤해요.', '그는 독일어를 해요.', '배고파?']),
 'lt': ('Esamasis laikas', "Kamienas + e, st, t, en, t, en: ich mache, du machst, er macht, wir machen, ihr macht, sie machen.\nsein: bin, bist, ist, sind, seid, sind. haben: habe, hast, hat, haben, habt, haben.\nStiprieji veiksmažodžiai keičia balsį su du ir er (fahren → du fährst, sehen → er sieht, sprechen → er spricht).\nMandagi forma: Sie + -en forma.", ['Esu pavargęs.', 'Jis kalba vokiškai.', 'Ar esi alkanas?']),
 'tl': ('Ang kasalukuyan', "Ugat + e, st, t, en, t, en: ich mache, du machst, er macht, wir machen, ihr macht, sie machen.\nsein: bin, bist, ist, sind, seid, sind. haben: habe, hast, hat, haben, habt, haben.\nMalalakas na pandiwa: nagbabago ang patinig sa du at er (fahren → du fährst, sehen → er sieht, sprechen → er spricht).\nMagalang: Sie + anyong -en.", ['Pagod ako.', 'Nagsasalita siya ng Aleman.', 'Gutom ka ba?']),
},
'ordre': {
 'es': ('La posición del verbo', "En una oración enunciativa, el verbo conjugado va siempre en segunda posición. Si se empieza por algo que no es el sujeto, el sujeto pasa detrás del verbo: Heute gehe ich ins Kino.\nPregunta de sí o no: verbo al principio (Kommst du?). Con palabra interrogativa: palabra + verbo (Wo wohnst du?).\nEl infinitivo y el participio van al final: Ich will Deutsch lernen.", ['Mañana voy a Berlín.', '¿Dónde vives?']),
 'it': ('La posizione del verbo', "Nella frase dichiarativa il verbo coniugato è sempre in seconda posizione. Se si comincia con qualcosa che non è il soggetto, il soggetto va dopo il verbo: Heute gehe ich ins Kino.\nDomanda sì / no: verbo in testa (Kommst du?). Con parola interrogativa: parola + verbo (Wo wohnst du?).\nInfinito e participio vanno in fondo: Ich will Deutsch lernen.", ['Domani vado a Berlino.', 'Dove abiti?']),
 'pt': ('A posição do verbo', "Na frase declarativa o verbo conjugado fica sempre na segunda posição. Se a frase começa por algo que não é o sujeito, o sujeito passa para depois do verbo: Heute gehe ich ins Kino.\nPergunta de sim ou não: verbo no início (Kommst du?). Com palavra interrogativa: palavra + verbo (Wo wohnst du?).\nInfinitivo e particípio vão para o fim: Ich will Deutsch lernen.", ['Amanhã vou a Berlim.', 'Onde você mora?']),
 'ja': ('動詞の位置', "平叙文では、活用した動詞はいつも二番目に置きます。主語以外で文を始めると、主語は動詞の後ろに来ます：Heute gehe ich ins Kino。\nはい・いいえで答える疑問文は動詞が先頭（Kommst du?）。疑問詞があれば疑問詞 + 動詞（Wo wohnst du?）。\n不定詞と過去分詞は文末に置きます：Ich will Deutsch lernen。", ['明日ベルリンへ行きます。', 'どこに住んでいるの？']),
 'zh': ('动词的位置', "陈述句中变位动词总在第二位。如果句首不是主语，主语就放到动词后：Heute gehe ich ins Kino。\n是非问句：动词放句首（Kommst du?）。有疑问词时：疑问词 + 动词（Wo wohnst du?）。\n不定式和过去分词放句末：Ich will Deutsch lernen。", ['我明天去柏林。', '你住在哪儿？']),
 'ko': ('동사의 위치', "평서문에서 활용된 동사는 항상 두 번째 자리에 옵니다. 주어가 아닌 다른 말로 문장을 시작하면 주어는 동사 뒤로 갑니다: Heute gehe ich ins Kino.\n예/아니요 의문문은 동사가 맨 앞(Kommst du?). 의문사가 있으면 의문사 + 동사(Wo wohnst du?).\n동사원형과 과거분사는 문장 끝에 옵니다: Ich will Deutsch lernen.", ['내일 베를린에 가요.', '어디 살아요?']),
 'lt': ('Veiksmažodžio vieta', "Tiesioginiame sakinyje asmenuojamas veiksmažodis visada antroje vietoje. Jei sakinys prasideda ne veiksniu, veiksnys eina po veiksmažodžio: Heute gehe ich ins Kino.\nTaip / ne klausimas: veiksmažodis pradžioje (Kommst du?). Su klausiamuoju žodžiu: žodis + veiksmažodis (Wo wohnst du?).\nBendratis ir dalyvis eina į galą: Ich will Deutsch lernen.", ['Rytoj važiuoju į Berlyną.', 'Kur tu gyveni?']),
 'tl': ('Ang posisyon ng pandiwa', "Sa paturol na pangungusap, laging nasa ikalawang posisyon ang binanghay na pandiwa. Kung hindi simuno ang nauuna, napupunta ang simuno pagkatapos ng pandiwa: Heute gehe ich ins Kino.\nTanong na oo / hindi: pandiwa sa unahan (Kommst du?). May salitang pananong: salita + pandiwa (Wo wohnst du?).\nNasa dulo ang infinitive at participle: Ich will Deutsch lernen.", ['Pupunta ako sa Berlin bukas.', 'Saan ka nakatira?']),
},
'accusatif': {
 'es': ('El acusativo', "Caso del complemento directo. Solo cambia el masculino: der → den, ein → einen, kein → keinen, mein → meinen. Femenino, neutro y plural se quedan como en nominativo.\nPronombres: mich, dich, ihn, sie, es, uns, euch, sie.\nSiempre con acusativo: für, ohne, durch, gegen, um.\n«Es gibt» + acusativo = hay.", ['Tengo un hermano.', 'Esto es para ti.']),
 'it': ("L'accusativo", "Caso del complemento oggetto. Cambia solo il maschile: der → den, ein → einen, kein → keinen, mein → meinen. Femminile, neutro e plurale restano come al nominativo.\nPronomi: mich, dich, ihn, sie, es, uns, euch, sie.\nSempre con l'accusativo: für, ohne, durch, gegen, um.\n«Es gibt» + accusativo = c'è, ci sono.", ['Ho un fratello.', 'Questo è per te.']),
 'pt': ('O acusativo', "Caso do complemento direto. Só o masculino muda: der → den, ein → einen, kein → keinen, mein → meinen. Feminino, neutro e plural ficam como no nominativo.\nPronomes: mich, dich, ihn, sie, es, uns, euch, sie.\nSempre com acusativo: für, ohne, durch, gegen, um.\n«Es gibt» + acusativo = há.", ['Tenho um irmão.', 'Isto é para você.']),
 'ja': ('4格（対格）', "直接目的語の格です。変わるのは男性だけ：der → den, ein → einen, kein → keinen, mein → meinen。女性・中性・複数は1格と同じ形です。\n代名詞：mich, dich, ihn, sie, es, uns, euch, sie。\nいつも4格をとる前置詞：für, ohne, durch, gegen, um。\n「es gibt」+ 4格 = 〜がある。", ['兄弟が一人います。', 'これはあなたにです。']),
 'zh': ('第四格（宾格）', "直接宾语的格。只有阳性发生变化：der → den，ein → einen，kein → keinen，mein → meinen。阴性、中性和复数与第一格相同。\n代词：mich, dich, ihn, sie, es, uns, euch, sie。\n总是支配第四格的介词：für, ohne, durch, gegen, um。\n「es gibt」+ 第四格 = 有。", ['我有一个兄弟。', '这是给你的。']),
 'ko': ('4격(목적격)', "직접 목적어의 격입니다. 남성만 바뀝니다: der → den, ein → einen, kein → keinen, mein → meinen. 여성, 중성, 복수는 1격과 같습니다.\n대명사: mich, dich, ihn, sie, es, uns, euch, sie.\n항상 4격을 쓰는 전치사: für, ohne, durch, gegen, um.\n「es gibt」+ 4격 = ~이 있다.", ['남자 형제가 한 명 있어요.', '이건 당신 거예요.']),
 'lt': ('Galininkas (Akkusativ)', "Tiesioginio papildinio linksnis. Keičiasi tik vyriškoji giminė: der → den, ein → einen, kein → keinen, mein → meinen. Moteriškoji, bevardė ir daugiskaita lieka kaip vardininke.\nĮvardžiai: mich, dich, ihn, sie, es, uns, euch, sie.\nVisada su galininku: für, ohne, durch, gegen, um.\n„Es gibt“ + galininkas = yra.", ['Turiu brolį.', 'Tai tau.']),
 'tl': ('Ang akusatibo', "Kaukulan ng tuwirang layon. Panlalaki lang ang nagbabago: der → den, ein → einen, kein → keinen, mein → meinen. Pareho sa nominatibo ang pambabae, walang kasarian at maramihan.\nPanghalip: mich, dich, ihn, sie, es, uns, euch, sie.\nLaging may akusatibo: für, ohne, durch, gegen, um.\n«Es gibt» + akusatibo = mayroon.", ['May kapatid akong lalaki.', 'Para sa iyo ito.']),
},
'negation': {
 'es': ('Nicht y kein', "«Kein» niega un sustantivo sin artículo o con artículo indefinido: Ich habe kein Auto.\n«Nicht» niega todo lo demás. Va al final para negar el verbo (Ich verstehe nicht), pero delante del adjetivo, el adverbio o el lugar: Das ist nicht gut. Er wohnt nicht hier.\nRespuesta afirmativa a una pregunta negativa: «doch».", ['No lo sé.', 'No tenemos dinero.']),
 'it': ('Nicht e kein', "«Kein» nega un nome senza articolo o con articolo indeterminativo: Ich habe kein Auto.\n«Nicht» nega tutto il resto. Va in fondo per negare il verbo (Ich verstehe nicht), ma davanti ad aggettivo, avverbio o luogo: Das ist nicht gut. Er wohnt nicht hier.\nRisposta affermativa a una domanda negativa: «doch».", ['Non lo so.', 'Non abbiamo soldi.']),
 'pt': ('Nicht e kein', "«Kein» nega um substantivo sem artigo ou com artigo indefinido: Ich habe kein Auto.\n«Nicht» nega o resto. Vai para o fim para negar o verbo (Ich verstehe nicht), mas antes do adjetivo, do advérbio ou do lugar: Das ist nicht gut. Er wohnt nicht hier.\nResposta afirmativa a uma pergunta negativa: «doch».", ['Não sei.', 'Não temos dinheiro.']),
 'ja': ('nicht と kein', "kein は無冠詞や不定冠詞つきの名詞を否定します：Ich habe kein Auto。\nnicht はそれ以外を否定します。動詞を否定するときは文末（Ich verstehe nicht）、形容詞・副詞・場所を否定するときはその前に置きます：Das ist nicht gut. Er wohnt nicht hier。\n否定の疑問に「いいえ、〜です」と肯定で答えるときは「doch」。", ['わかりません。', '私たちはお金がありません。']),
 'zh': ('nicht 与 kein', "kein 否定无冠词或带不定冠词的名词：Ich habe kein Auto。\nnicht 否定其他成分。否定动词时放句末（Ich verstehe nicht），否定形容词、副词或地点时放在它们前面：Das ist nicht gut. Er wohnt nicht hier。\n对否定疑问句作肯定回答用「doch」。", ['我不知道。', '我们没有钱。']),
 'ko': ('nicht와 kein', "kein은 관사가 없거나 부정관사가 붙는 명사를 부정합니다: Ich habe kein Auto.\nnicht는 그 밖의 것을 부정합니다. 동사를 부정할 때는 문장 끝(Ich verstehe nicht), 형용사·부사·장소를 부정할 때는 그 앞에 둡니다: Das ist nicht gut. Er wohnt nicht hier.\n부정 의문문에 긍정으로 답할 때는 「doch」.", ['몰라요.', '우리는 돈이 없어요.']),
 'lt': ('Nicht ir kein', "„Kein“ neigia daiktavardį be artikelio arba su nežymimuoju artikeliu: Ich habe kein Auto.\n„Nicht“ neigia visa kita. Neigiant veiksmažodį jis eina į galą (Ich verstehe nicht), bet prieš būdvardį, prieveiksmį ar vietą: Das ist nicht gut. Er wohnt nicht hier.\nTeigiamas atsakymas į neigiamą klausimą: „doch“.", ['Nežinau.', 'Neturime pinigų.']),
 'tl': ('Nicht at kein', "Ang «kein» ay nagkakaila sa pangngalang walang pantukoy o may di-tiyak na pantukoy: Ich habe kein Auto.\nAng «nicht» ang nagkakaila sa iba. Nasa dulo kapag pandiwa (Ich verstehe nicht), pero bago ang pang-uri, pang-abay o lugar: Das ist nicht gut. Er wohnt nicht hier.\nPositibong sagot sa negatibong tanong: «doch».", ['Hindi ko alam.', 'Wala kaming pera.']),
},
'modaux': {
 'es': ('Los verbos modales', "können (poder, saber), müssen (tener que), wollen (querer), dürfen (tener permiso), sollen (deber, por encargo de otro), mögen / möchten (gustar / querer).\nSingular irregular, sin terminación en ich y er: ich kann, du kannst, er kann; muss, will, darf, soll, mag.\nEl infinitivo va al final: Ich kann gut schwimmen.", ['Quisiera un café.', 'Tienes que irte ya.']),
 'it': ('I verbi modali', "können (potere, sapere), müssen (dovere), wollen (volere), dürfen (avere il permesso), sollen (dovere, per volontà altrui), mögen / möchten (piacere / volere).\nSingolare irregolare, senza desinenza con ich ed er: ich kann, du kannst, er kann; muss, will, darf, soll, mag.\nL'infinito va in fondo: Ich kann gut schwimmen.", ['Vorrei un caffè.', 'Devi andare adesso.']),
 'pt': ('Os verbos modais', "können (poder, saber), müssen (ter de), wollen (querer), dürfen (ter permissão), sollen (dever, por ordem de outrem), mögen / möchten (gostar / querer).\nSingular irregular, sem terminação em ich e er: ich kann, du kannst, er kann; muss, will, darf, soll, mag.\nO infinitivo vai para o fim: Ich kann gut schwimmen.", ['Eu queria um café.', 'Você tem de ir agora.']),
 'ja': ('話法の助動詞', "können（できる）、müssen（〜しなければならない）、wollen（〜したい）、dürfen（〜してよい）、sollen（〜すべきだ、人に言われて）、mögen / möchten（好きだ／〜したい）。\n単数は不規則で、ich と er には語尾がつきません：ich kann, du kannst, er kann、muss, will, darf, soll, mag。\n不定詞は文末に置きます：Ich kann gut schwimmen。", ['コーヒーをください。', 'もう行かなきゃだめだよ。']),
 'zh': ('情态动词', "können（能、会），müssen（必须），wollen（想要），dürfen（允许），sollen（应该，出于他人要求），mögen / möchten（喜欢／想要）。\n单数不规则，ich 和 er 没有词尾：ich kann, du kannst, er kann；muss, will, darf, soll, mag。\n不定式放句末：Ich kann gut schwimmen。", ['我想要一杯咖啡。', '你现在必须走了。']),
 'ko': ('화법 조동사', "können(할 수 있다), müssen(해야 한다), wollen(하고 싶다), dürfen(해도 된다), sollen(해야 한다, 남의 뜻으로), mögen / möchten(좋아하다 / 원하다).\n단수는 불규칙이며 ich와 er에는 어미가 없습니다: ich kann, du kannst, er kann, muss, will, darf, soll, mag.\n동사원형은 문장 끝에 옵니다: Ich kann gut schwimmen.", ['커피 한 잔 주세요.', '이제 가야 해.']),
 'lt': ('Modaliniai veiksmažodžiai', "können (galėti, mokėti), müssen (privalėti), wollen (norėti), dürfen (turėti leidimą), sollen (turėti, kitų nurodymu), mögen / möchten (mėgti / norėtų).\nVienaskaita netaisyklinga, be galūnės su ich ir er: ich kann, du kannst, er kann; muss, will, darf, soll, mag.\nBendratis eina į galą: Ich kann gut schwimmen.", ['Norėčiau kavos.', 'Tau dabar reikia eiti.']),
 'tl': ('Mga modal na pandiwa', "können (kaya, marunong), müssen (kailangan), wollen (gusto), dürfen (pinapayagan), sollen (dapat, utos ng iba), mögen / möchten (gusto / nais).\nDi-regular ang isahan, walang hulapi sa ich at er: ich kann, du kannst, er kann; muss, will, darf, soll, mag.\nNasa dulo ang infinitive: Ich kann gut schwimmen.", ['Gusto ko ng kape.', 'Kailangan mo nang umalis.']),
},
'datif': {
 'es': ('El dativo', "Caso del complemento indirecto (¿a quién?). Artículos: dem (masculino y neutro), der (femenino), den + -n en el sustantivo (plural); einem, einer.\nPronombres: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.\nSiempre con dativo: aus, bei, mit, nach, seit, von, zu, gegenüber. Contracciones: zum, zur, vom, beim, im, am.\nVerbos con dativo: helfen, danken, gefallen, gehören.", ['Te ayudo.', 'Va en autobús.']),
 'it': ('Il dativo', "Caso del complemento di termine (a chi?). Articoli: dem (maschile e neutro), der (femminile), den + -n sul nome (plurale); einem, einer.\nPronomi: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.\nSempre con il dativo: aus, bei, mit, nach, seit, von, zu, gegenüber. Contrazioni: zum, zur, vom, beim, im, am.\nVerbi con il dativo: helfen, danken, gefallen, gehören.", ['Ti aiuto.', 'Va in autobus.']),
 'pt': ('O dativo', "Caso do complemento indireto (a quem?). Artigos: dem (masculino e neutro), der (feminino), den + -n no substantivo (plural); einem, einer.\nPronomes: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.\nSempre com dativo: aus, bei, mit, nach, seit, von, zu, gegenüber. Contrações: zum, zur, vom, beim, im, am.\nVerbos com dativo: helfen, danken, gefallen, gehören.", ['Eu te ajudo.', 'Ele vai de ônibus.']),
 'ja': ('3格（与格）', "間接目的語（誰に）の格です。冠詞：dem（男性・中性）、der（女性）、den + 名詞に -n（複数）。einem, einer。\n代名詞：mir, dir, ihm, ihr, ihm, uns, euch, ihnen。\nいつも3格をとる前置詞：aus, bei, mit, nach, seit, von, zu, gegenüber。融合形：zum, zur, vom, beim, im, am。\n3格をとる動詞：helfen, danken, gefallen, gehören。", ['手伝うよ。', '彼はバスで行きます。']),
 'zh': ('第三格（与格）', "间接宾语（给谁）的格。冠词：dem（阳性、中性），der（阴性），den + 名词加 -n（复数）；einem, einer。\n代词：mir, dir, ihm, ihr, ihm, uns, euch, ihnen。\n总是支配第三格的介词：aus, bei, mit, nach, seit, von, zu, gegenüber。缩合：zum, zur, vom, beim, im, am。\n支配第三格的动词：helfen, danken, gefallen, gehören。", ['我帮你。', '他坐公共汽车去。']),
 'ko': ('3격(여격)', "간접 목적어(누구에게)의 격입니다. 관사: dem(남성, 중성), der(여성), den + 명사에 -n(복수), einem, einer.\n대명사: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.\n항상 3격을 쓰는 전치사: aus, bei, mit, nach, seit, von, zu, gegenüber. 축약: zum, zur, vom, beim, im, am.\n3격을 쓰는 동사: helfen, danken, gefallen, gehören.", ['도와줄게.', '그는 버스로 가요.']),
 'lt': ('Naudininkas (Dativ)', "Netiesioginio papildinio linksnis (kam?). Artikeliai: dem (vyr. ir bevardė), der (mot.), den + -n prie daiktavardžio (daugiskaita); einem, einer.\nĮvardžiai: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.\nVisada su naudininku: aus, bei, mit, nach, seit, von, zu, gegenüber. Sutraukimai: zum, zur, vom, beim, im, am.\nVeiksmažodžiai su naudininku: helfen, danken, gefallen, gehören.", ['Aš tau padedu.', 'Jis važiuoja autobusu.']),
 'tl': ('Ang datibo', "Kaukulan ng di-tuwirang layon (kanino?). Pantukoy: dem (panlalaki at walang kasarian), der (pambabae), den + -n sa pangngalan (maramihan); einem, einer.\nPanghalip: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.\nLaging may datibo: aus, bei, mit, nach, seit, von, zu, gegenüber. Pagsasama: zum, zur, vom, beim, im, am.\nPandiwang may datibo: helfen, danken, gefallen, gehören.", ['Tutulungan kita.', 'Sumasakay siya ng bus.']),
},
'prepositions-mixtes': {
 'es': ('Preposiciones de doble caso', "an, auf, hinter, in, neben, über, unter, vor, zwischen llevan acusativo si hay movimiento hacia un lugar (wohin?) y dativo si indican posición (wo?).\nIch gehe in die Stadt (voy) / Ich bin in der Stadt (estoy). Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch.", ['El libro está en la mesa.', 'Vamos al cine.']),
 'it': ('Preposizioni con due casi', "an, auf, hinter, in, neben, über, unter, vor, zwischen vogliono l'accusativo se c'è movimento verso un luogo (wohin?) e il dativo se indicano posizione (wo?).\nIch gehe in die Stadt (ci vado) / Ich bin in der Stadt (ci sono). Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch.", ['Il libro è sul tavolo.', 'Andiamo al cinema.']),
 'pt': ('Preposições de dois casos', "an, auf, hinter, in, neben, über, unter, vor, zwischen pedem acusativo quando há movimento para um lugar (wohin?) e dativo quando indicam posição (wo?).\nIch gehe in die Stadt (vou) / Ich bin in der Stadt (estou). Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch.", ['O livro está na mesa.', 'Vamos ao cinema.']),
 'ja': ('3格・4格支配の前置詞', "an, auf, hinter, in, neben, über, unter, vor, zwischen は、ある場所へ移動するとき（wohin?）は4格、位置を表すとき（wo?）は3格をとります。\nIch gehe in die Stadt（町へ行く）/ Ich bin in der Stadt（町にいる）。Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch。", ['本はテーブルの上にあります。', '映画に行きます。']),
 'zh': ('支配第三、四格的介词', "an, auf, hinter, in, neben, über, unter, vor, zwischen 表示向某处移动（wohin?）时用第四格，表示位置（wo?）时用第三格。\nIch gehe in die Stadt（去城里）/ Ich bin in der Stadt（在城里）。Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch。", ['书在桌子上。', '我们去电影院。']),
 'ko': ('3격·4격 지배 전치사', "an, auf, hinter, in, neben, über, unter, vor, zwischen은 어떤 장소로 이동할 때(wohin?)는 4격, 위치를 나타낼 때(wo?)는 3격을 씁니다.\nIch gehe in die Stadt(시내로 간다) / Ich bin in der Stadt(시내에 있다). Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch.", ['책은 탁자 위에 있어요.', '우리는 영화관에 가요.']),
 'lt': ('Prielinksniai su dviem linksniais', "an, auf, hinter, in, neben, über, unter, vor, zwischen valdo galininką, kai judama į vietą (wohin?), ir naudininką, kai nurodoma vieta (wo?).\nIch gehe in die Stadt (einu į miestą) / Ich bin in der Stadt (esu mieste). Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch.", ['Knyga guli ant stalo.', 'Einame į kiną.']),
 'tl': ('Pang-ukol na may dalawang kaukulan', "Ang an, auf, hinter, in, neben, über, unter, vor, zwischen ay akusatibo kapag may galaw papunta (wohin?) at datibo kapag posisyon (wo?).\nIch gehe in die Stadt (pupunta) / Ich bin in der Stadt (naroon). Ich lege das Buch auf den Tisch / Das Buch liegt auf dem Tisch.", ['Nasa mesa ang libro.', 'Manonood kami ng sine.']),
},
'separables': {
 'es': ('Verbos con partícula separable', "Muchos verbos llevan una partícula acentuada (an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…). En presente y pretérito se separa y va al final: anrufen → Ich rufe dich an. aufstehen → Er steht früh auf.\nEn el participio, ge- se intercala: angerufen, aufgestanden.\nLos prefijos be-, ge-, er-, ver-, zer-, ent-, emp- nunca se separan.", ['Me levanto a las siete.', '¿Cuándo llegas?']),
 'it': ('Verbi con particella separabile', "Molti verbi hanno una particella accentata (an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…). Al presente e al preterito si stacca e va in fondo: anrufen → Ich rufe dich an. aufstehen → Er steht früh auf.\nNel participio ge- si inserisce: angerufen, aufgestanden.\nI prefissi be-, ge-, er-, ver-, zer-, ent-, emp- non si separano mai.", ['Mi alzo alle sette.', 'Quando arrivi?']),
 'pt': ('Verbos com partícula separável', "Muitos verbos têm uma partícula tônica (an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…). No presente e no pretérito ela se separa e vai para o fim: anrufen → Ich rufe dich an. aufstehen → Er steht früh auf.\nNo particípio, ge- intercala-se: angerufen, aufgestanden.\nOs prefixos be-, ge-, er-, ver-, zer-, ent-, emp- nunca se separam.", ['Levanto às sete.', 'Quando você chega?']),
 'ja': ('分離動詞', "アクセントのある前つづり（an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…）を持つ動詞が多くあります。現在形と過去形では前つづりが離れて文末に行きます：anrufen → Ich rufe dich an。aufstehen → Er steht früh auf。\n過去分詞では ge- が間に入ります：angerufen, aufgestanden。\nbe-, ge-, er-, ver-, zer-, ent-, emp- は決して分離しません。", ['7時に起きます。', 'いつ着くの？']),
 'zh': ('可分动词', "许多动词带有重读前缀（an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…）。在现在时和过去时中前缀分离并放到句末：anrufen → Ich rufe dich an。aufstehen → Er steht früh auf。\n过去分词中 ge- 插在中间：angerufen, aufgestanden。\n前缀 be-, ge-, er-, ver-, zer-, ent-, emp- 永不分离。", ['我七点起床。', '你什么时候到？']),
 'ko': ('분리 동사', "강세가 있는 전철(an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…)이 붙은 동사가 많습니다. 현재형과 과거형에서는 전철이 떨어져 문장 끝으로 갑니다: anrufen → Ich rufe dich an. aufstehen → Er steht früh auf.\n과거분사에서는 ge-가 사이에 들어갑니다: angerufen, aufgestanden.\nbe-, ge-, er-, ver-, zer-, ent-, emp-는 절대 분리되지 않습니다.", ['저는 일곱 시에 일어나요.', '언제 도착해요?']),
 'lt': ('Veiksmažodžiai su atskiriamuoju priešdėliu', "Daug veiksmažodžių turi kirčiuotą dalelę (an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…). Esamajame ir būtajame laike ji atsiskiria ir eina į galą: anrufen → Ich rufe dich an. aufstehen → Er steht früh auf.\nDalyvyje ge- įsiterpia: angerufen, aufgestanden.\nPriešdėliai be-, ge-, er-, ver-, zer-, ent-, emp- niekada neatsiskiria.", ['Keliuosi septintą.', 'Kada atvyksti?']),
 'tl': ('Pandiwang may naghihiwalay na unlapi', "Maraming pandiwa ang may diinang unlapi (an-, auf-, aus-, ein-, mit-, zu-, vor-, ab-…). Sa kasalukuyan at preterite, humihiwalay ito at napupunta sa dulo: anrufen → Ich rufe dich an. aufstehen → Er steht früh auf.\nSa participle, isinisingit ang ge-: angerufen, aufgestanden.\nHindi kailanman humihiwalay ang be-, ge-, er-, ver-, zer-, ent-, emp-.", ['Gumigising ako nang alas-siyete.', 'Kailan ka darating?']),
},
'parfait': {
 'es': ('El perfecto (pretérito compuesto)', "haben o sein en presente + participio al final. Participio: ge- + raíz + -t (gemacht) en verbos débiles, ge- + raíz + -en (gesehen, gegangen) en fuertes; sin ge- en los verbos en -ieren y con prefijo inseparable (studiert, besucht).\n«Sein» con verbos de movimiento o cambio de estado (gehen, fahren, kommen, werden, sterben) y con sein, bleiben.\nEs el pasado de la lengua hablada.", ['Vi una película.', 'Ella se fue a casa.']),
 'it': ('Il passato prossimo (Perfekt)', "haben o sein al presente + participio in fondo. Participio: ge- + radice + -t (gemacht) per i verbi deboli, ge- + radice + -en (gesehen, gegangen) per i forti; niente ge- per i verbi in -ieren e con prefisso inseparabile (studiert, besucht).\n«Sein» con i verbi di movimento o di cambiamento di stato (gehen, fahren, kommen, werden, sterben) e con sein, bleiben.\nÈ il passato della lingua parlata.", ['Ho visto un film.', 'È tornata a casa.']),
 'pt': ('O perfeito (Perfekt)', "haben ou sein no presente + particípio no fim. Particípio: ge- + radical + -t (gemacht) nos verbos fracos, ge- + radical + -en (gesehen, gegangen) nos fortes; sem ge- nos verbos em -ieren e com prefixo inseparável (studiert, besucht).\n«Sein» com verbos de movimento ou mudança de estado (gehen, fahren, kommen, werden, sterben) e com sein, bleiben.\nÉ o passado da língua falada.", ['Vi um filme.', 'Ela foi para casa.']),
 'ja': ('現在完了形', "haben または sein の現在形 + 文末に過去分詞。過去分詞：弱変化は ge- + 語幹 + -t（gemacht）、強変化は ge- + 語幹 + -en（gesehen, gegangen）。-ieren 動詞と非分離動詞には ge- がつきません（studiert, besucht）。\n移動や状態の変化を表す動詞（gehen, fahren, kommen, werden, sterben）と sein, bleiben は sein を使います。\n話し言葉の過去です。", ['映画を見ました。', '彼女は家に帰りました。']),
 'zh': ('现在完成时', "haben 或 sein 的现在时 + 句末过去分词。过去分词：弱变化动词为 ge- + 词干 + -t（gemacht），强变化动词为 ge- + 词干 + -en（gesehen, gegangen）；以 -ieren 结尾和带不可分前缀的动词不加 ge-（studiert, besucht）。\n表示位移或状态变化的动词（gehen, fahren, kommen, werden, sterben）以及 sein、bleiben 用 sein。\n这是口语中的过去时。", ['我看了一部电影。', '她回家了。']),
 'ko': ('현재완료', "haben 또는 sein 현재형 + 문장 끝에 과거분사. 과거분사: 약변화는 ge- + 어간 + -t(gemacht), 강변화는 ge- + 어간 + -en(gesehen, gegangen), -ieren 동사와 비분리 동사에는 ge-가 없습니다(studiert, besucht).\n이동이나 상태 변화를 나타내는 동사(gehen, fahren, kommen, werden, sterben)와 sein, bleiben은 sein을 씁니다.\n말할 때 쓰는 과거입니다.", ['영화를 봤어요.', '그녀는 집에 갔어요.']),
 'lt': ('Perfektas (sudėtinis būtasis)', "haben arba sein esamuoju laiku + dalyvis gale. Dalyvis: silpniesiems ge- + kamienas + -t (gemacht), stipriesiems ge- + kamienas + -en (gesehen, gegangen); be ge- veiksmažodžiams su -ieren ir neatskiriamuoju priešdėliu (studiert, besucht).\n„Sein“ – su judėjimo ar būsenos pasikeitimo veiksmažodžiais (gehen, fahren, kommen, werden, sterben) ir su sein, bleiben.\nTai šnekamosios kalbos būtasis laikas.", ['Pažiūrėjau filmą.', 'Ji grįžo namo.']),
 'tl': ('Ang perfect (Perfekt)', "haben o sein sa kasalukuyan + participle sa dulo. Participle: ge- + ugat + -t (gemacht) sa mahihinang pandiwa, ge- + ugat + -en (gesehen, gegangen) sa malalakas; walang ge- sa pandiwang -ieren at may di-naghihiwalay na unlapi (studiert, besucht).\n«Sein» sa pandiwa ng galaw o pagbabago ng kalagayan (gehen, fahren, kommen, werden, sterben) at sa sein, bleiben.\nIto ang nakaraan sa pagsasalita.", ['Nanood ako ng pelikula.', 'Umuwi siya.']),
},
'subordonnees': {
 'es': ('Subordinadas: el verbo al final', "Tras weil (porque), dass (que), wenn (si, cuando), ob (si), als (cuando, pasado), obwohl (aunque), bevor, nachdem, damit, el verbo conjugado va al final: Ich bleibe zu Hause, weil ich krank bin.\nSiempre hay una coma entre las dos oraciones. Si la subordinada va primero, la principal empieza por su verbo: Wenn es regnet, bleibe ich hier.\nTras und, aber, oder, denn el orden no cambia.", ['Creo que tiene razón.', 'No sé si viene.']),
 'it': ('Le subordinate: il verbo in fondo', "Dopo weil (perché), dass (che), wenn (se, quando), ob (se), als (quando, passato), obwohl (benché), bevor, nachdem, damit, il verbo coniugato va in fondo: Ich bleibe zu Hause, weil ich krank bin.\nUna virgola separa sempre le due proposizioni. Se la subordinata viene prima, la principale comincia con il suo verbo: Wenn es regnet, bleibe ich hier.\nDopo und, aber, oder, denn l'ordine non cambia.", ['Credo che abbia ragione.', 'Non so se viene.']),
 'pt': ('Subordinadas: o verbo no fim', "Depois de weil (porque), dass (que), wenn (se, quando), ob (se), als (quando, passado), obwohl (embora), bevor, nachdem, damit, o verbo conjugado vai para o fim: Ich bleibe zu Hause, weil ich krank bin.\nUma vírgula separa sempre as orações. Se a subordinada vem primeiro, a principal começa pelo verbo: Wenn es regnet, bleibe ich hier.\nDepois de und, aber, oder, denn a ordem não muda.", ['Acho que ele tem razão.', 'Não sei se ela vem.']),
 'ja': ('従属文：動詞は文末へ', "weil（なぜなら）、dass（〜ということ）、wenn（もし、〜するとき）、ob（〜かどうか）、als（〜したとき、過去）、obwohl（〜にもかかわらず）、bevor、nachdem、damit の後では、活用した動詞が文末に行きます：Ich bleibe zu Hause, weil ich krank bin。\n二つの文の間には必ずコンマを打ちます。従属文が先に来ると、主文は動詞から始まります：Wenn es regnet, bleibe ich hier。\nund, aber, oder, denn の後では語順は変わりません。", ['彼は正しいと思います。', '彼女が来るかどうかわかりません。']),
 'zh': ('从句：动词放句末', "在 weil（因为），dass（……这件事），wenn（如果，当……时），ob（是否），als（当……时，过去），obwohl（尽管），bevor，nachdem，damit 之后，变位动词放在从句末尾：Ich bleibe zu Hause, weil ich krank bin。\n主从句之间总用逗号隔开。从句在前时，主句以动词开头：Wenn es regnet, bleibe ich hier。\nund, aber, oder, denn 之后语序不变。", ['我认为他是对的。', '我不知道她来不来。']),
 'ko': ('종속절: 동사는 끝으로', "weil(왜냐하면), dass(~라는 것), wenn(만약, ~할 때), ob(~인지), als(~했을 때, 과거), obwohl(~에도 불구하고), bevor, nachdem, damit 뒤에서는 활용된 동사가 맨 끝으로 갑니다: Ich bleibe zu Hause, weil ich krank bin.\n두 절 사이에는 항상 쉼표를 찍습니다. 종속절이 먼저 오면 주절은 동사로 시작합니다: Wenn es regnet, bleibe ich hier.\nund, aber, oder, denn 뒤에서는 어순이 바뀌지 않습니다.", ['그가 옳다고 생각해요.', '그녀가 올지 모르겠어요.']),
 'lt': ('Šalutiniai sakiniai: veiksmažodis gale', "Po weil (nes), dass (kad), wenn (jei, kai), ob (ar), als (kai, praeityje), obwohl (nors), bevor, nachdem, damit asmenuojamas veiksmažodis eina į galą: Ich bleibe zu Hause, weil ich krank bin.\nSakinius visada skiria kablelis. Jei šalutinis eina pirmas, pagrindinis prasideda veiksmažodžiu: Wenn es regnet, bleibe ich hier.\nPo und, aber, oder, denn tvarka nesikeičia.", ['Manau, kad jis teisus.', 'Nežinau, ar ji ateis.']),
 'tl': ('Mga sugnay na pantulong: pandiwa sa dulo', "Pagkatapos ng weil (dahil), dass (na), wenn (kung, kapag), ob (kung), als (noong), obwohl (kahit), bevor, nachdem, damit, napupunta sa dulo ang binanghay na pandiwa: Ich bleibe zu Hause, weil ich krank bin.\nLaging may kuwit sa pagitan ng dalawang sugnay. Kung nauna ang pantulong, nagsisimula sa pandiwa ang pangunahin: Wenn es regnet, bleibe ich hier.\nPagkatapos ng und, aber, oder, denn, hindi nagbabago ang ayos.", ['Sa tingin ko tama siya.', 'Hindi ko alam kung darating siya.']),
},
'comparaison': {
 'es': ('Comparativo y superlativo', "Comparativo: adjetivo + -er + als (schneller als). Superlativo: am + -sten (am schnellsten) o der / die / das -ste.\nA menudo con diéresis: alt → älter, groß → größer, jung → jünger. Irregulares: gut → besser → am besten, viel → mehr → am meisten, gern → lieber → am liebsten.\nIgualdad: so … wie.", ['Es mayor que yo.', 'Prefiero beber té.']),
 'it': ('Comparativo e superlativo', "Comparativo: aggettivo + -er + als (schneller als). Superlativo: am + -sten (am schnellsten) o der / die / das -ste.\nSpesso con l'Umlaut: alt → älter, groß → größer, jung → jünger. Irregolari: gut → besser → am besten, viel → mehr → am meisten, gern → lieber → am liebsten.\nUguaglianza: so … wie.", ['È più vecchio di me.', 'Preferisco bere tè.']),
 'pt': ('Comparativo e superlativo', "Comparativo: adjetivo + -er + als (schneller als). Superlativo: am + -sten (am schnellsten) ou der / die / das -ste.\nMuitas vezes com trema: alt → älter, groß → größer, jung → jünger. Irregulares: gut → besser → am besten, viel → mehr → am meisten, gern → lieber → am liebsten.\nIgualdade: so … wie.", ['Ele é mais velho do que eu.', 'Prefiro beber chá.']),
 'ja': ('比較級と最上級', "比較級：形容詞 + -er + als（schneller als）。最上級：am + -sten（am schnellsten）または der / die / das -ste。\nウムラウトがつくことが多い：alt → älter, groß → größer, jung → jünger。不規則：gut → besser → am besten、viel → mehr → am meisten、gern → lieber → am liebsten。\n同等：so … wie。", ['彼は私より年上です。', '紅茶のほうが好きです。']),
 'zh': ('比较级和最高级', "比较级：形容词 + -er + als（schneller als）。最高级：am + -sten（am schnellsten）或 der / die / das -ste。\n常带变元音：alt → älter，groß → größer，jung → jünger。不规则：gut → besser → am besten，viel → mehr → am meisten，gern → lieber → am liebsten。\n同级：so … wie。", ['他比我年纪大。', '我更喜欢喝茶。']),
 'ko': ('비교급과 최상급', "비교급: 형용사 + -er + als(schneller als). 최상급: am + -sten(am schnellsten) 또는 der / die / das -ste.\n움라우트가 붙는 경우가 많습니다: alt → älter, groß → größer, jung → jünger. 불규칙: gut → besser → am besten, viel → mehr → am meisten, gern → lieber → am liebsten.\n동등: so … wie.", ['그는 저보다 나이가 많아요.', '저는 차를 더 좋아해요.']),
 'lt': ('Aukštesnysis ir aukščiausiasis laipsnis', "Aukštesnysis: būdvardis + -er + als (schneller als). Aukščiausiasis: am + -sten (am schnellsten) arba der / die / das -ste.\nDažnai su umliautu: alt → älter, groß → größer, jung → jünger. Netaisyklingi: gut → besser → am besten, viel → mehr → am meisten, gern → lieber → am liebsten.\nLygybė: so … wie.", ['Jis vyresnis už mane.', 'Labiau mėgstu gerti arbatą.']),
 'tl': ('Paghahambing', "Paghahambing: pang-uri + -er + als (schneller als). Pinakamataas: am + -sten (am schnellsten) o der / die / das -ste.\nMadalas may umlaut: alt → älter, groß → größer, jung → jünger. Di-regular: gut → besser → am besten, viel → mehr → am meisten, gern → lieber → am liebsten.\nPagkakapantay: so … wie.", ['Mas matanda siya sa akin.', 'Mas gusto kong uminom ng tsaa.']),
},
'preterit': {
 'es': ('El pretérito (Präteritum)', "Tiempo de la narración escrita; al hablar se usa sobre todo con sein, haben y los modales: war, hatte, konnte, musste, wollte.\nVerbos débiles: raíz + te (machte, machtest, machte, machten, machtet, machten). Verbos fuertes: cambio de vocal, sin terminación en ich y er (ging, kam, sah, fuhr, gab, nahm).", ['Ayer estaba enfermo.', 'No tenía tiempo.']),
 'it': ('Il preterito (Präteritum)', "Tempo del racconto scritto; nel parlato si usa soprattutto con sein, haben e i modali: war, hatte, konnte, musste, wollte.\nVerbi deboli: radice + te (machte, machtest, machte, machten, machtet, machten). Verbi forti: cambio di vocale, senza desinenza con ich ed er (ging, kam, sah, fuhr, gab, nahm).", ['Ieri ero malato.', 'Non aveva tempo.']),
 'pt': ('O pretérito (Präteritum)', "Tempo da narração escrita; na fala usa-se sobretudo com sein, haben e os modais: war, hatte, konnte, musste, wollte.\nVerbos fracos: radical + te (machte, machtest, machte, machten, machtet, machten). Verbos fortes: mudança de vogal, sem terminação em ich e er (ging, kam, sah, fuhr, gab, nahm).", ['Ontem eu estava doente.', 'Ele não tinha tempo.']),
 'ja': ('過去形', "書き言葉の物語で使う時制です。話し言葉ではおもに sein, haben と話法の助動詞に使います：war, hatte, konnte, musste, wollte。\n弱変化：語幹 + te（machte, machtest, machte, machten, machtet, machten）。強変化：母音が変わり、ich と er には語尾がつきません（ging, kam, sah, fuhr, gab, nahm）。", ['昨日は病気でした。', '彼には時間がありませんでした。']),
 'zh': ('过去时', "书面叙述用的时态；口语中主要用于 sein、haben 和情态动词：war, hatte, konnte, musste, wollte。\n弱变化动词：词干 + te（machte, machtest, machte, machten, machtet, machten）。强变化动词：元音改变，ich 和 er 无词尾（ging, kam, sah, fuhr, gab, nahm）。", ['我昨天生病了。', '他没有时间。']),
 'ko': ('과거형', "글로 쓰는 이야기의 시제입니다. 말할 때는 주로 sein, haben과 화법 조동사에 씁니다: war, hatte, konnte, musste, wollte.\n약변화: 어간 + te(machte, machtest, machte, machten, machtet, machten). 강변화: 모음이 바뀌고 ich와 er에는 어미가 없습니다(ging, kam, sah, fuhr, gab, nahm).", ['어제 아팠어요.', '그는 시간이 없었어요.']),
 'lt': ('Būtasis laikas (Präteritum)', "Rašytinio pasakojimo laikas; šnekant daugiausia vartojamas su sein, haben ir modaliniais: war, hatte, konnte, musste, wollte.\nSilpnieji: kamienas + te (machte, machtest, machte, machten, machtet, machten). Stiprieji: balsio kaita, be galūnės su ich ir er (ging, kam, sah, fuhr, gab, nahm).", ['Vakar sirgau.', 'Jis neturėjo laiko.']),
 'tl': ('Ang preterite (Präteritum)', "Panahunan ng nakasulat na salaysay; sa usapan, karaniwan lang sa sein, haben at mga modal: war, hatte, konnte, musste, wollte.\nMahihinang pandiwa: ugat + te (machte, machtest, machte, machten, machtet, machten). Malalakas: nagbabago ang patinig, walang hulapi sa ich at er (ging, kam, sah, fuhr, gab, nahm).", ['May sakit ako kahapon.', 'Wala siyang oras.']),
},
'genitif-adjectif': {
 'es': ('El genitivo y la declinación del adjetivo', "Genitivo (posesión): des / eines + sustantivo en -(e)s en masculino y neutro, der / einer en femenino y plural. Das Auto meines Vaters. Preposiciones: wegen, während, trotz, statt.\nEl adjetivo delante del sustantivo se declina. Tras der / die / das: -e en nominativo singular, -en casi en todo lo demás (der gute Wein, mit dem guten Wein). Tras ein, el adjetivo marca el género (ein guter Wein, ein gutes Buch). Sin artículo, toma la terminación del artículo (guter Wein).", ['Es la casa de mis padres.', 'Lleva un vestido rojo.']),
 'it': ("Il genitivo e la declinazione dell'aggettivo", "Genitivo (possesso): des / eines + nome in -(e)s al maschile e al neutro, der / einer al femminile e al plurale. Das Auto meines Vaters. Preposizioni: wegen, während, trotz, statt.\nL'aggettivo attributivo si declina. Dopo der / die / das: -e al nominativo singolare, -en quasi ovunque altrove (der gute Wein, mit dem guten Wein). Dopo ein, l'aggettivo porta il segno del genere (ein guter Wein, ein gutes Buch). Senza articolo, prende la desinenza dell'articolo (guter Wein).", ['È la casa dei miei genitori.', 'Indossa un vestito rosso.']),
 'pt': ('O genitivo e a declinação do adjetivo', "Genitivo (posse): des / eines + substantivo em -(e)s no masculino e neutro, der / einer no feminino e plural. Das Auto meines Vaters. Preposições: wegen, während, trotz, statt.\nO adjetivo antes do substantivo declina-se. Depois de der / die / das: -e no nominativo singular, -en quase em todo o resto (der gute Wein, mit dem guten Wein). Depois de ein, o adjetivo marca o gênero (ein guter Wein, ein gutes Buch). Sem artigo, recebe a terminação do artigo (guter Wein).", ['É a casa dos meus pais.', 'Ela usa um vestido vermelho.']),
 'ja': ('2格（属格）と形容詞の格変化', "2格（所有）：男性・中性は des / eines + 名詞に -(e)s、女性・複数は der / einer。Das Auto meines Vaters。2格をとる前置詞：wegen, während, trotz, statt。\n名詞の前の形容詞は語尾が変化します。der / die / das の後：1格単数で -e、それ以外ほぼ -en（der gute Wein, mit dem guten Wein）。ein の後は形容詞が性を示します（ein guter Wein, ein gutes Buch）。冠詞がなければ定冠詞の語尾をとります（guter Wein）。", ['これは私の両親の家です。', '彼女は赤いドレスを着ています。']),
 'zh': ('第二格与形容词变格', "第二格（所属）：阳性和中性用 des / eines + 名词加 -(e)s，阴性和复数用 der / einer。Das Auto meines Vaters。支配第二格的介词：wegen, während, trotz, statt。\n名词前的形容词要变格。在 der / die / das 之后：第一格单数加 -e，其余几乎都加 -en（der gute Wein, mit dem guten Wein）。在 ein 之后，形容词显示性（ein guter Wein, ein gutes Buch）。无冠词时，形容词带定冠词的词尾（guter Wein）。", ['这是我父母的房子。', '她穿着一条红裙子。']),
 'ko': ('2격(소유격)과 형용사 어미 변화', "2격(소유): 남성·중성은 des / eines + 명사에 -(e)s, 여성·복수는 der / einer. Das Auto meines Vaters. 2격을 쓰는 전치사: wegen, während, trotz, statt.\n명사 앞의 형용사는 어미가 변합니다. der / die / das 뒤: 1격 단수는 -e, 나머지는 거의 -en(der gute Wein, mit dem guten Wein). ein 뒤에서는 형용사가 성을 나타냅니다(ein guter Wein, ein gutes Buch). 관사가 없으면 정관사 어미를 받습니다(guter Wein).", ['이건 우리 부모님 집이에요.', '그녀는 빨간 원피스를 입고 있어요.']),
 'lt': ('Kilmininkas ir būdvardžio linksniavimas', "Kilmininkas (priklausomybė): des / eines + daiktavardis su -(e)s vyriškojoje ir bevardėje, der / einer moteriškojoje ir daugiskaitoje. Das Auto meines Vaters. Prielinksniai: wegen, während, trotz, statt.\nPažyminys būdvardis linksniuojamas. Po der / die / das: -e vardininko vienaskaitoje, -en beveik visur kitur (der gute Wein, mit dem guten Wein). Po ein būdvardis rodo giminę (ein guter Wein, ein gutes Buch). Be artikelio jis gauna artikelio galūnę (guter Wein).", ['Tai mano tėvų namas.', 'Ji vilki raudoną suknelę.']),
 'tl': ('Ang genitibo at ang pagbabago ng pang-uri', "Genitibo (pag-aari): des / eines + pangngalang may -(e)s sa panlalaki at walang kasarian, der / einer sa pambabae at maramihan. Das Auto meines Vaters. Pang-ukol: wegen, während, trotz, statt.\nNagbabago ang pang-uring nasa unahan ng pangngalan. Pagkatapos ng der / die / das: -e sa nominatibong isahan, -en halos sa iba pa (der gute Wein, mit dem guten Wein). Pagkatapos ng ein, ang pang-uri ang nagpapakita ng kasarian (ein guter Wein, ein gutes Buch). Kung walang pantukoy, kinukuha nito ang hulapi ng pantukoy (guter Wein).", ['Ito ang bahay ng mga magulang ko.', 'Nakasuot siya ng pulang bestida.']),
},
'futur-passif': {
 'es': ('Werden: futuro y pasiva', "werden: werde, wirst, wird, werden, werdet, werden.\nFuturo: werden + infinitivo al final (Ich werde kommen). A menudo basta el presente con una indicación de tiempo: Morgen komme ich.\nPasiva: werden + participio (Das Haus wird gebaut). Pasado: wurde gebaut; perfecto: ist gebaut worden. Agente: von + dativo.\nSolo, werden significa «llegar a ser»: Er wird Arzt.", ['Pronto va a llover.', 'El coche fue reparado.']),
 'it': ('Werden: futuro e passivo', "werden: werde, wirst, wird, werden, werdet, werden.\nFuturo: werden + infinito in fondo (Ich werde kommen). Spesso basta il presente con un'indicazione di tempo: Morgen komme ich.\nPassivo: werden + participio (Das Haus wird gebaut). Passato: wurde gebaut; perfetto: ist gebaut worden. Agente: von + dativo.\nDa solo, werden significa «diventare»: Er wird Arzt.", ['Presto pioverà.', 'La macchina è stata riparata.']),
 'pt': ('Werden: futuro e passiva', "werden: werde, wirst, wird, werden, werdet, werden.\nFuturo: werden + infinitivo no fim (Ich werde kommen). Muitas vezes basta o presente com uma indicação de tempo: Morgen komme ich.\nPassiva: werden + particípio (Das Haus wird gebaut). Passado: wurde gebaut; perfeito: ist gebaut worden. Agente: von + dativo.\nSozinho, werden significa «tornar-se»: Er wird Arzt.", ['Logo vai chover.', 'O carro foi consertado.']),
 'ja': ('werden：未来と受動態', "werden：werde, wirst, wird, werden, werdet, werden。\n未来：werden + 文末に不定詞（Ich werde kommen）。時を表す語があれば現在形で十分なことが多い：Morgen komme ich。\n受動態：werden + 過去分詞（Das Haus wird gebaut）。過去：wurde gebaut、現在完了：ist gebaut worden。動作主：von + 3格。\n単独の werden は「〜になる」：Er wird Arzt。", ['もうすぐ雨が降ります。', '車は修理されました。']),
 'zh': ('werden：将来时与被动语态', "werden：werde, wirst, wird, werden, werdet, werden。\n将来时：werden + 句末不定式（Ich werde kommen）。有时间状语时常用现在时即可：Morgen komme ich。\n被动语态：werden + 过去分词（Das Haus wird gebaut）。过去时：wurde gebaut；完成时：ist gebaut worden。施事者：von + 第三格。\n单独使用时 werden 表示「成为」：Er wird Arzt。", ['快要下雨了。', '汽车被修好了。']),
 'ko': ('werden: 미래와 수동태', "werden: werde, wirst, wird, werden, werdet, werden.\n미래: werden + 문장 끝 동사원형(Ich werde kommen). 시간 표현이 있으면 현재형으로 충분할 때가 많습니다: Morgen komme ich.\n수동태: werden + 과거분사(Das Haus wird gebaut). 과거: wurde gebaut, 현재완료: ist gebaut worden. 행위자: von + 3격.\nwerden만 쓰면 「~이 되다」입니다: Er wird Arzt.", ['곧 비가 올 거예요.', '차가 수리되었어요.']),
 'lt': ('Werden: būsimasis laikas ir neveikiamoji rūšis', "werden: werde, wirst, wird, werden, werdet, werden.\nBūsimasis: werden + bendratis gale (Ich werde kommen). Dažnai užtenka esamojo laiko su laiko žodžiu: Morgen komme ich.\nNeveikiamoji: werden + dalyvis (Das Haus wird gebaut). Būtasis: wurde gebaut; perfektas: ist gebaut worden. Veikėjas: von + naudininkas.\nVienas werden reiškia „tapti“: Er wird Arzt.", ['Netrukus lis.', 'Automobilis buvo sutaisytas.']),
 'tl': ('Werden: hinaharap at balintiyak', "werden: werde, wirst, wird, werden, werdet, werden.\nHinaharap: werden + infinitive sa dulo (Ich werde kommen). Madalas sapat na ang kasalukuyan na may salitang pang-oras: Morgen komme ich.\nBalintiyak: werden + participle (Das Haus wird gebaut). Nakaraan: wurde gebaut; perfect: ist gebaut worden. Gumagawa: von + datibo.\nKapag nag-iisa, «maging» ang werden: Er wird Arzt.", ['Uulan na maya-maya.', 'Naayos ang kotse.']),
},
'relatives': {
 'es': ('Las oraciones de relativo', "El pronombre relativo se parece al artículo definido: der, die, das, die; acusativo den; dativo dem, der, dem, denen; genitivo dessen, deren. Toma el género de su antecedente y el caso de su función en la relativa.\nEl verbo va al final y la relativa va entre comas: Der Mann, den ich gesehen habe, ist mein Lehrer.", ['Es la mujer que trabaja aquí.']),
 'it': ('Le proposizioni relative', "Il pronome relativo assomiglia all'articolo determinativo: der, die, das, die; accusativo den; dativo dem, der, dem, denen; genitivo dessen, deren. Prende il genere del suo antecedente e il caso della sua funzione nella relativa.\nIl verbo va in fondo e la relativa sta tra virgole: Der Mann, den ich gesehen habe, ist mein Lehrer.", ['È la donna che lavora qui.']),
 'pt': ('As orações relativas', "O pronome relativo parece o artigo definido: der, die, das, die; acusativo den; dativo dem, der, dem, denen; genitivo dessen, deren. Toma o gênero do antecedente e o caso da sua função na relativa.\nO verbo vai para o fim e a relativa fica entre vírgulas: Der Mann, den ich gesehen habe, ist mein Lehrer.", ['É a mulher que trabalha aqui.']),
 'ja': ('関係文', "関係代名詞は定冠詞に似ています：der, die, das, die、4格 den、3格 dem, der, dem, denen、2格 dessen, deren。性は先行詞に、格は関係文の中での役割に合わせます。\n動詞は文末に置き、関係文はコンマではさみます：Der Mann, den ich gesehen habe, ist mein Lehrer。", ['ここで働いている女性です。']),
 'zh': ('关系从句', "关系代词与定冠词相似：der, die, das, die；第四格 den；第三格 dem, der, dem, denen；第二格 dessen, deren。它的性取决于先行词，格取决于它在从句中的作用。\n动词放在从句末尾，从句用逗号隔开：Der Mann, den ich gesehen habe, ist mein Lehrer。", ['这是在这里工作的那位女士。']),
 'ko': ('관계문', "관계대명사는 정관사와 비슷합니다: der, die, das, die, 4격 den, 3격 dem, der, dem, denen, 2격 dessen, deren. 성은 선행사에, 격은 관계문 안에서의 역할에 맞춥니다.\n동사는 끝에 오고 관계문은 쉼표 사이에 둡니다: Der Mann, den ich gesehen habe, ist mein Lehrer.", ['여기서 일하는 여자예요.']),
 'lt': ('Santykiniai šalutiniai sakiniai', "Santykinis įvardis panašus į žymimąjį artikelį: der, die, das, die; galininkas den; naudininkas dem, der, dem, denen; kilmininkas dessen, deren. Jis gauna antecedento giminę ir linksnį pagal savo funkciją sakinyje.\nVeiksmažodis eina į galą, sakinys atskiriamas kableliais: Der Mann, den ich gesehen habe, ist mein Lehrer.", ['Tai moteris, kuri čia dirba.']),
 'tl': ('Mga sugnay na relatibo', "Kahawig ng tiyak na pantukoy ang relatibong panghalip: der, die, das, die; akusatibo den; datibo dem, der, dem, denen; genitibo dessen, deren. Kinukuha nito ang kasarian ng tinutukoy at ang kaukulan ayon sa gamit nito sa sugnay.\nNasa dulo ang pandiwa at nasa pagitan ng kuwit ang sugnay: Der Mann, den ich gesehen habe, ist mein Lehrer.", ['Siya ang babaeng nagtatrabaho rito.']),
},
'konjunktiv2': {
 'es': ('El subjuntivo II: hipótesis y cortesía', "Formas frecuentes: wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge. Para los demás verbos: würde + infinitivo (Ich würde gehen).\nHipótesis irreal: Wenn ich Zeit hätte, würde ich reisen. Pasado: Wenn ich das gewusst hätte, wäre ich gekommen.\nCortesía: Könnten Sie mir helfen? Ich hätte gern…\nDeseo: Wenn ich doch reich wäre!", ['Quisiera una cerveza.', 'Yo que tú, me quedaría.']),
 'it': ('Il congiuntivo II: ipotesi e cortesia', "Forme frequenti: wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge. Per gli altri verbi: würde + infinito (Ich würde gehen).\nIpotesi irreale: Wenn ich Zeit hätte, würde ich reisen. Passato: Wenn ich das gewusst hätte, wäre ich gekommen.\nCortesia: Könnten Sie mir helfen? Ich hätte gern…\nDesiderio: Wenn ich doch reich wäre!", ['Vorrei una birra.', 'Al tuo posto resterei.']),
 'pt': ('O subjuntivo II: hipótese e cortesia', "Formas frequentes: wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge. Para os outros verbos: würde + infinitivo (Ich würde gehen).\nHipótese irreal: Wenn ich Zeit hätte, würde ich reisen. Passado: Wenn ich das gewusst hätte, wäre ich gekommen.\nCortesia: Könnten Sie mir helfen? Ich hätte gern…\nDesejo: Wenn ich doch reich wäre!", ['Eu queria uma cerveja.', 'No seu lugar, eu ficaria.']),
 'ja': ('接続法第2式：仮定と丁寧', "よく使う形：wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge。そのほかの動詞は würde + 不定詞（Ich würde gehen）。\n事実に反する仮定：Wenn ich Zeit hätte, würde ich reisen。過去：Wenn ich das gewusst hätte, wäre ich gekommen。\n丁寧な依頼：Könnten Sie mir helfen? Ich hätte gern…\n願望：Wenn ich doch reich wäre!", ['ビールを一杯ください。', '私があなたなら残ります。']),
 'zh': ('第二虚拟式：假设与礼貌', "常用形式：wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge。其他动词用 würde + 不定式（Ich würde gehen）。\n非真实假设：Wenn ich Zeit hätte, würde ich reisen。过去：Wenn ich das gewusst hätte, wäre ich gekommen。\n礼貌请求：Könnten Sie mir helfen? Ich hätte gern…\n愿望：Wenn ich doch reich wäre!", ['我想要一杯啤酒。', '如果我是你，我会留下。']),
 'ko': ('접속법 2식: 가정과 공손', "자주 쓰는 형태: wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge. 다른 동사는 würde + 동사원형(Ich würde gehen).\n사실과 반대되는 가정: Wenn ich Zeit hätte, würde ich reisen. 과거: Wenn ich das gewusst hätte, wäre ich gekommen.\n공손한 부탁: Könnten Sie mir helfen? Ich hätte gern…\n소망: Wenn ich doch reich wäre!", ['맥주 한 잔 주세요.', '제가 너라면 남을 거예요.']),
 'lt': ('Konjunktyvas II: prielaida ir mandagumas', "Dažnos formos: wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge. Kitiems veiksmažodžiams: würde + bendratis (Ich würde gehen).\nNereali prielaida: Wenn ich Zeit hätte, würde ich reisen. Praeitis: Wenn ich das gewusst hätte, wäre ich gekommen.\nMandagumas: Könnten Sie mir helfen? Ich hätte gern…\nNoras: Wenn ich doch reich wäre!", ['Norėčiau alaus.', 'Tavo vietoje pasilikčiau.']),
 'tl': ('Konjunktiv II: hinuha at paggalang', "Madalas na anyo: wäre, hätte, würde, könnte, müsste, sollte, dürfte, wüsste, käme, ginge. Sa ibang pandiwa: würde + infinitive (Ich würde gehen).\nDi-totoong hinuha: Wenn ich Zeit hätte, würde ich reisen. Nakaraan: Wenn ich das gewusst hätte, wäre ich gekommen.\nPaggalang: Könnten Sie mir helfen? Ich hätte gern…\nHiling: Wenn ich doch reich wäre!", ['Isang beer nga po.', 'Kung ako ikaw, mananatili ako.']),
},
'infinitif-zu': {
 'es': ('El infinitivo con zu; um … zu', "Tras muchos verbos y expresiones, el infinitivo lleva «zu» delante: Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen. Con un verbo separable, zu se intercala: anzurufen.\nSin zu tras los modales, werden, lassen, sehen, hören.\nFinalidad: um … zu (para). Sin: ohne … zu. En lugar de: statt … zu.", ['No tengo ganas de trabajar.', 'Aprende alemán para estudiar en Berlín.']),
 'it': ("L'infinito con zu; um … zu", "Dopo molti verbi ed espressioni, l'infinito è preceduto da «zu»: Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen. Con un verbo separabile, zu si inserisce: anzurufen.\nNiente zu dopo i modali, werden, lassen, sehen, hören.\nScopo: um … zu (per). Senza: ohne … zu. Invece di: statt … zu.", ['Non ho voglia di lavorare.', 'Studia tedesco per studiare a Berlino.']),
 'pt': ('O infinitivo com zu; um … zu', "Depois de muitos verbos e expressões, o infinitivo leva «zu» antes: Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen. Com verbo separável, zu intercala-se: anzurufen.\nSem zu depois dos modais, werden, lassen, sehen, hören.\nFinalidade: um … zu (para). Sem: ohne … zu. Em vez de: statt … zu.", ['Não estou com vontade de trabalhar.', 'Ele aprende alemão para estudar em Berlim.']),
 'ja': ('zu 不定詞と um … zu', "多くの動詞や表現の後では、不定詞の前に zu を置きます：Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen。分離動詞では zu が間に入ります：anzurufen。\n話法の助動詞、werden、lassen、sehen、hören の後は zu をつけません。\n目的：um … zu（〜するために）。〜せずに：ohne … zu。〜する代わりに：statt … zu。", ['働く気になれません。', '彼はベルリンの大学で学ぶためにドイツ語を勉強しています。']),
 'zh': ('带 zu 的不定式；um … zu', "在许多动词和短语后，不定式前要加 zu：Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen。可分动词的 zu 插在中间：anzurufen。\n情态动词、werden、lassen、sehen、hören 后不用 zu。\n目的：um … zu（为了）。不……就：ohne … zu。代替：statt … zu。", ['我不想工作。', '他学德语是为了在柏林上大学。']),
 'ko': ('zu 부정사와 um … zu', "많은 동사와 표현 뒤에서는 동사원형 앞에 zu를 둡니다: Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen. 분리 동사는 zu가 사이에 들어갑니다: anzurufen.\n화법 조동사, werden, lassen, sehen, hören 뒤에는 zu를 쓰지 않습니다.\n목적: um … zu(~하기 위해). ~하지 않고: ohne … zu. ~하는 대신: statt … zu.", ['일할 기분이 아니에요.', '그는 베를린에서 공부하려고 독일어를 배워요.']),
 'lt': ('Bendratis su zu; um … zu', "Po daugelio veiksmažodžių ir posakių bendratis turi „zu“: Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen. Su atskiriamuoju veiksmažodžiu zu įsiterpia: anzurufen.\nBe zu po modalinių, werden, lassen, sehen, hören.\nTikslas: um … zu (kad). Be: ohne … zu. Užuot: statt … zu.", ['Neturiu noro dirbti.', 'Jis mokosi vokiečių kalbos, kad galėtų studijuoti Berlyne.']),
 'tl': ('Ang infinitive na may zu; um … zu', "Pagkatapos ng maraming pandiwa at pahayag, may «zu» bago ang infinitive: Ich versuche, Deutsch zu lernen. Es ist schwer, das zu verstehen. Sa pandiwang naghihiwalay, isinisingit ang zu: anzurufen.\nWalang zu pagkatapos ng modal, werden, lassen, sehen, hören.\nLayunin: um … zu (para). Nang hindi: ohne … zu. Sa halip na: statt … zu.", ['Wala akong ganang magtrabaho.', 'Nag-aaral siya ng Aleman para makapag-aral sa Berlin.']),
},
'konjunktiv1': {
 'es': ('El subjuntivo I: estilo indirecto', "En la prensa y en la lengua escrita se refieren las palabras de otros en subjuntivo I para mostrar que no se asumen: Er sagt, er sei krank. Sie sagte, sie habe keine Zeit.\nFormación: raíz del infinitivo + e, est, e, en, et, en (er komme, er habe, er könne); sein: sei, seist, sei, seien.\nCuando la forma coincide con el indicativo, se usa el subjuntivo II: Sie sagten, sie hätten…", ['Dijo que estaba cansado.']),
 'it': ('Il congiuntivo I: discorso riportato', "Nella stampa e nella lingua scritta si riferiscono le parole altrui al congiuntivo I per mostrare che non ci si assume la responsabilità di ciò che si riferisce: Er sagt, er sei krank. Sie sagte, sie habe keine Zeit.\nFormazione: radice dell'infinito + e, est, e, en, et, en (er komme, er habe, er könne); sein: sei, seist, sei, seien.\nQuando la forma coincide con l'indicativo, si usa il congiuntivo II: Sie sagten, sie hätten…", ['Ha detto che era stanco.']),
 'pt': ('O subjuntivo I: discurso indireto', "Na imprensa e na língua escrita, as palavras alheias são relatadas no subjuntivo I para mostrar que não se assumem: Er sagt, er sei krank. Sie sagte, sie habe keine Zeit.\nFormação: radical do infinitivo + e, est, e, en, et, en (er komme, er habe, er könne); sein: sei, seist, sei, seien.\nQuando a forma coincide com o indicativo, usa-se o subjuntivo II: Sie sagten, sie hätten…", ['Ele disse que estava cansado.']),
 'ja': ('接続法第1式：間接話法', "新聞や書き言葉では、他人の言葉を伝えるときに接続法第1式を使い、書き手が内容を保証しないことを示します：Er sagt, er sei krank. Sie sagte, sie habe keine Zeit。\n作り方：不定詞の語幹 + e, est, e, en, et, en（er komme, er habe, er könne）。sein：sei, seist, sei, seien。\n直説法と同じ形になるときは接続法第2式を使います：Sie sagten, sie hätten…", ['彼は疲れていると言いました。']),
 'zh': ('第一虚拟式：间接引语', "在报刊和书面语中，转述他人的话时用第一虚拟式，表示作者不对内容负责：Er sagt, er sei krank. Sie sagte, sie habe keine Zeit。\n构成：不定式词干 + e, est, e, en, et, en（er komme, er habe, er könne）；sein：sei, seist, sei, seien。\n形式与直陈式相同时，改用第二虚拟式：Sie sagten, sie hätten…", ['他说他很累。']),
 'ko': ('접속법 1식: 간접 화법', "신문이나 글에서 남의 말을 전할 때 접속법 1식을 써서 글쓴이가 그 내용을 보증하지 않음을 나타냅니다: Er sagt, er sei krank. Sie sagte, sie habe keine Zeit.\n만드는 법: 동사원형 어간 + e, est, e, en, et, en(er komme, er habe, er könne), sein: sei, seist, sei, seien.\n직설법과 형태가 같으면 접속법 2식을 씁니다: Sie sagten, sie hätten…", ['그는 피곤하다고 말했어요.']),
 'lt': ('Konjunktyvas I: netiesioginė kalba', "Spaudoje ir rašytinėje kalboje kitų žodžiai perteikiami konjunktyvu I, parodant, kad rašantysis už juos neatsako: Er sagt, er sei krank. Sie sagte, sie habe keine Zeit.\nDaroma: bendraties kamienas + e, est, e, en, et, en (er komme, er habe, er könne); sein: sei, seist, sei, seien.\nKai forma sutampa su tiesiogine nuosaka, vartojamas konjunktyvas II: Sie sagten, sie hätten…", ['Jis sakė esąs pavargęs.']),
 'tl': ('Konjunktiv I: di-tuwirang pananalita', "Sa pahayagan at pasulat na wika, iniuulat ang sinabi ng iba sa Konjunktiv I para ipakitang hindi ito pinaninindigan ng sumulat: Er sagt, er sei krank. Sie sagte, sie habe keine Zeit.\nPagbuo: ugat ng infinitive + e, est, e, en, et, en (er komme, er habe, er könne); sein: sei, seist, sei, seien.\nKapag kapareho ng indikatibo ang anyo, Konjunktiv II ang gamit: Sie sagten, sie hätten…", ['Sinabi niyang pagod siya.']),
},
}
